@n4 syntax.nominal dependent="the" head="rest"
@r2 syntax.relation marker="of" from=$n4 to=$n5
@n5 syntax.nominal dependent="the" head="scene"
@r3 syntax.relation marker="as" from=$c3 to=$c4
@n6 syntax.nominal head="it"
@c4 syntax.clause form=declarative verb="is" subject=$n6
@r4 syntax.relation from=$n2 to=$c3
@r5 syntax.relation from=$n2 to=$c2

sop:
@c1 syntax.clause form=imperative verb="let" complement=$n1
@n1 syntax.nominal head="'s"
@c2 syntax.clause form=nonfinite verb="finish" modifier="just" complement=$n2
@n2 syntax.nominal head="it"
@r1 syntax.relation marker="with" from=$c2 to=$c3
@n3 syntax.nominal dependent="a" head="rabbit"
@r2 syntax.relation marker="beside" from=$n3 to=$n4
@n4 syntax.nominal dependent="the" head="garden"
@c3 syntax.clause form=nonfinite verb="facing" modifier="right" subject=$n3
@r3 syntax.relation marker="like" from=$c2 to=$n5
@n5 syntax.nominal head="that"
@r4 syntax.relation from=$c1 to=$c2

alt:
@c1 syntax.clause form=imperative verb="let" modifier="just" complement=$n1
@n1 syntax.nominal head="'s"
@c2 syntax.clause form=nonfinite verb="finish" subject=$n1 complement=$n2
@n2 syntax.nominal head="it"
@r1 syntax.relation marker="with" from=$c2 to=$n3
@n3 syntax.nominal dependent="a" head="rabbit"
@r2 syntax.relation marker="beside" from=$n3 to=$n4
@n4 syntax.nominal dependent="the" head="garden"
@c3 syntax.clause form=nonfinite verb="facing" modifier="right"
@r3 syntax.relation marker="like" from=$c1 to=$n5
@n5 syntax.nominal head="that"
@r4 syntax.relation from=$c1 to=$c2
@r5 syntax.relation from=$n3 to=$c3
